"""Build the V2 content, theme tokens and editable examples using only Python stdlib.
Run from any directory: python3 V2/12_Developer/build-v2.py
Original logo masters are intentionally never modified.
"""
from pathlib import Path
import json, re, hashlib, csv, html, shutil

ROOT = Path(__file__).resolve().parents[1]
SOURCE = ROOT.parent / 'V1/extracted/Condo-Ninja-Brand'
def write(path, text):
    p = ROOT / path; p.parent.mkdir(parents=True, exist_ok=True); p.write_text(text, encoding='utf-8')
def dump(path, value): write(path, json.dumps(value, ensure_ascii=False, indent=2)+'\n')

tokens=json.loads((SOURCE/'03_Color/brand-tokens.json').read_text())
tokens.pop('$schema',None)
tokens.update(version='2.0.0', description='Tokens simples de implementação. Não declara conformidade com um schema DTCG.')
tokens['typography']['family']['brand']='"Condo Goldman", sans-serif'
tokens['theme']={
 'light':{'background':'#FAFBFD','surface':'#FFFFFF','surfaceSubtle':'#F2F5F9','text':'#050B1A','muted':'#34507F','border':'#C9D6EA','controlBorder':'#6B85AD','accent':'#0B4BB5','action':'#1B6BFF','onAction':'#FFFFFF','focus':'#0B4BB5','positive':'#166534','positiveSurface':'#DCFCE7','attention':'#854D0E','attentionSurface':'#FEF3C7','alert':'#B42318','alertSurface':'#FEE4E2','verified':'#115E59','verifiedSurface':'#CCFBF1'},
 'dark':{'background':'#050B1A','surface':'#0A1428','surfaceSubtle':'#101E3A','text':'#FAFBFD','muted':'#9AB0D0','border':'#23385F','controlBorder':'#6B85AD','accent':'#5AC8FF','action':'#5AC8FF','onAction':'#050B1A','focus':'#5AC8FF','positive':'#4ADE80','positiveSurface':'#123327','attention':'#F6C453','attentionSurface':'#302611','alert':'#FF8A7A','alertSurface':'#341C23','verified':'#2DD4BF','verifiedSurface':'#0C302E'}
}
tokens['component']={'targetMin':'44px','focusWidth':'3px','focusOffset':'4px','readingWidth':'66ch','wordmarkWeight':400,'chartLineWidth':'3px'}
tokens['motion']['reduced']={'duration':'0.01ms','iterations':1,'scrollBehavior':'auto'}
tokens['opacity']['disabled']=1
tokens['color']['semantic'].update(focusLight='#0B4BB5',focusDark='#5AC8FF',linkLight='#0B4BB5',linkDark='#74D1FF')
for folder in ['03_Color','12_Developer']:dump(folder+'/brand-tokens.json',tokens)
def kebab(s):return re.sub(r'([A-Z])',r'-\1',s).lower()
css=['/* Generated from brand-tokens.json. Theme: data-theme="light" | "dark". */',':root {']
for group in ['ink','paper','signal','functional','special','base']:
 for name,val in tokens['color'][group].items():css.append(f'  --cn-{group}-{kebab(name)}: {val};')
for group,prefix in [('spacing','space'),('radius','radius'),('shadow','shadow'),('opacity','opacity'),('gradient','gradient'),('border','border')]:
 for name,val in tokens[group].items():css.append(f'  --cn-{prefix}-{kebab(name)}: {val};')
for group,prefix in [('family','font'),('size','text'),('weight','weight'),('lineHeight','leading'),('tracking','tracking')]:
 for name,val in tokens['typography'][group].items():css.append(f'  --cn-{prefix}-{kebab(name)}: {val};')
for group,prefix in [('duration','duration'),('easing','ease')]:
 for name,val in tokens['motion'][group].items():css.append(f'  --cn-{prefix}-{name}: {val};')
for name,val in tokens['component'].items():css.append(f'  --cn-{kebab(name)}: {val};')
css.append('}')
for mode,values in tokens['theme'].items():
 css.append((':root, ' if mode=='light' else '')+f'[data-theme="{mode}"] {{')
 css.extend(f'  --cn-{kebab(name)}: {val};' for name,val in values.items());css.append('}')
css.append('@media (prefers-reduced-motion: reduce) { :root { --cn-duration-fast: 0.01ms; --cn-duration-standard: 0.01ms; --cn-duration-deliberate: 0.01ms; } }')
for folder in ['03_Color','12_Developer']:write(folder+'/variables.css','\n'.join(css)+'\n')
write('12_Developer/tailwind-brand-config.js','/** Tailwind v3 ESM extension. See README for Tailwind v4. */\nexport default '+json.dumps({'theme':{'extend':{'colors':{g:tokens['color'][g] for g in ['ink','paper','signal']},'fontFamily':{'brand':['Condo Goldman','sans-serif'],'sans':['Geist','sans-serif'],'mono':['Geist Mono','monospace']},'borderRadius':tokens['radius']}}},indent=2)+';\n')
write('12_Developer/tailwind-brand-v4.css','/* Import variables.css first, then this after your Tailwind v4 import. */\n@theme inline {\n --color-cn-background: var(--cn-background);\n --color-cn-surface: var(--cn-surface);\n --color-cn-text: var(--cn-text);\n --color-cn-accent: var(--cn-accent);\n --color-cn-action: var(--cn-action);\n --font-brand: "Condo Goldman", sans-serif;\n --font-sans: Geist, sans-serif;\n --font-mono: "Geist Mono", monospace;\n}\n')

data={'disclosure':'DADOS FICTÍCIOS PARA DEMONSTRAÇÃO. Não representam mercado ou condomínio real.','currency':'BRL','unit':'R$/elevador/mês','period':'Jan-Jun 2026','scope':'Manutenção preventiva de um elevador, sem peças ou modernização.','geography':'Recorte geográfico fictício; substituir antes de uso real.','sampleSize':12,'sampleType':'Amostra sintética, sem validade estatística','months':['Jan','Fev','Mar','Abr','Mai','Jun'],'observed':[1200,1250,1300,1450,1600,1800],'lower':[1100]*6,'upper':[1500]*6,'sources':[{'id':'DEMO-01','name':'Contrato de manutenção (fictício)','status':'disponível'},{'id':'DEMO-02','name':'Tabela de preços comparáveis (sintética)','status':'disponível'},{'id':'DEMO-03','name':'Aditivo de escopo','status':'faltante'}],'confidence':{'label':'Limitada','reason':'O aditivo não está disponível e a amostra é sintética.'},'finding':'Junho está 20% acima do limite superior ilustrativo.','formula':'(1800 / 1500 - 1) × 100 = 20%','nextStep':'Solicitar o aditivo e confirmar peças, plantões e escopo antes de comparar.'}
dump('08_Data_Visualization/examples/benchmark-demo.json',data)

def lum(h):
 a=[int(h[i:i+2],16)/255 for i in (1,3,5)];a=[v/12.92 if v<=.04045 else ((v+.055)/1.055)**2.4 for v in a];return sum(v*w for v,w in zip(a,[.2126,.7152,.0722]))
def contrast(a,b):
 x,y=sorted([lum(a),lum(b)]);return (y+.05)/(x+.05)
rows=[]
for mode,v in tokens['theme'].items():
 for fg,bg in [('text','background'),('muted','surface'),('accent','background'),('onAction','action'),('focus','background'),('positive','positiveSurface'),('attention','attentionSurface'),('alert','alertSurface'),('verified','verifiedSurface'),('controlBorder','surface')]:
  ratio=contrast(v[fg],v[bg]);threshold=3 if fg in ['focus','controlBorder'] else 4.5
  rows.append({'theme':mode,'foreground':fg,'background':bg,'foregroundHex':v[fg],'backgroundHex':v[bg],'ratio':round(ratio,3),'threshold':threshold,'pass':ratio>=threshold})
dump('03_Color/contrast-audit.json',rows)
assert all(r['pass'] for r in rows),rows

