page('PALETA ESTENDIDA','Profundidade\ncom funções claras.','As escalas completas permanecem nos tokens. Não escolher tons apenas por proximidade visual.', [('Ink','950, 900 e 800: fundos. 600 e 500: texto em superfícies claras. 300 e 200: texto secundário em fundos escuros.'),('Signal','500: assinatura e ação no tema escuro. 700: botão no tema claro. 800: link e foco no tema claro.'),('Gradientes','Restritos ao símbolo e a campos gráficos de marca. Gráficos quantitativos usam cores estáveis.'),('Proporção','Uma cor de destaque por hierarquia. Dar espaço ao conteúdo e evitar preencher cada componente de azul.')],kind='palette')
page('STATUS','Cor acompanha\num significado escrito.','As cores funcionais são subordinadas à identidade. Um estado precisa continuar claro sem percepção de cor.', [('Concluído','Check e rótulo. Verde indica uma etapa concluída, sem declarar boa governança.'),('Atenção','Triângulo, motivo e ação. Âmbar indica revisão necessária.'),('Erro','Mensagem do que falhou e como corrigir. Coral não indica culpa.'),('Verificado','Identificar o objeto e o responsável pela verificação. Não confundir documento conferido com conclusão validada.')],kind='status')
page('ACESSIBILIDADE','O par de cores\né a unidade de decisão.','V2 fornece pares semânticos próprios para temas claro e escuro, com contraste calculado.', [('Texto comum','Exigir pelo menos 4,5:1. Não arredondar um resultado abaixo do limite para aprová-lo.'),('Controles e foco','Borda funcional e indicador de foco precisam de contraste suficiente com a superfície adjacente.'),('Erros de V1 corrigidos','Um único token de foco azul claro falha em fundo claro. V2 usa Signal 800 no claro e Signal 500 no escuro.'),('Auditoria','Consultar 03_Color/contrast-audit.json. A aprovação dos pares não substitui a avaliação da interface completa.')],kind='contrast')
page('TIPOGRAFIA','Três funções.\nUma hierarquia.','A marca, a leitura e os dados exigem ritmos diferentes.', [('Goldman Regular 400','Assinatura. Usar apenas no wordmark e em pequenas expressões de marca.'),('Geist Sans 400 / 500 / 600','Conteúdo, títulos, interface e comunicação.'),('Geist Mono 400 / 500','Valores, identificadores, metadados e trechos técnicos. Números tabulares ajudam a comparação.'),('Licenças','Conservar os avisos OFL junto às fontes. Conferir os textos de licença antes de redistribuir um subconjunto.')],kind='type')
page('ESCALA TIPOGRÁFICA','Leitura antes\ndo efeito tipográfico.','No digital, corpo de 16–18 px e entrelinha de 1,5. Títulos grandes devem quebrar sem comprimir o conteúdo.', [('Display','48–88 px, entrelinha de 1,02–1,1. Reservado à abertura.'),('Títulos','H1 40–56 px. H2 30–40 px. H3 22–26 px.'),('Interface','14–16 px em labels e controles. Evitar texto essencial abaixo de 14 px.'),('Refluxo','Testar 320 px e ampliação de texto. Quebrar palavras longas e reorganizar colunas, em vez de esconder overflow.')],kind='type')
page('ICONOGRAFIA','Objetos reconhecíveis.\nTraço preciso.','A família recebida contém 17 ícones funcionais em uma grade de 24 px.', [('Construção','Traço de 1,8 px, terminais controlados e curvas econômicas. Não usar o símbolo como ícone de todas as funções.'),('Família','Financeiro, contratos, fornecedores, elevadores, manutenção, obras, água, energia, documentos e governança.'),('Continuidade','Jurídico, segurança, evidências, benchmark, investigação, comunidade e mobilização.'),('Acessibilidade','Ícone decorativo recebe alt vazio. Ação sem texto precisa de nome acessível. Em estados relevantes, sempre incluir rótulo visível.')],kind='icons')
page('SISTEMA GRÁFICO','A informação ganha\num campo de evidência.','O elemento proprietário da V2 é a relação visível entre afirmação, fonte e limite.', [('Faceta','Concentra atenção em uma área, com formas derivadas do símbolo.'),('Campo de evidência','Uma afirmação acompanhada por origem, período e situação da revisão.'),('Linha de relação','Conecta dois elementos com significado. Evitar redes decorativas sem conteúdo.'),('Foco','Um destaque por composição. Textura permanece subordinada à legibilidade.')])
page('GRID E COMPOSIÇÃO','Ordem que deixa\no conteúdo respirar.','Alinhamentos previsíveis reduzem esforço de leitura.', [('Desktop','12 colunas, gutter de 24–32 px e largura de conteúdo limitada.'),('Mobile','4 colunas, gutter de 16 px e controles com área de toque mínima de 44 px.'),('Ritmo','Usar a escala de 4 px. Agrupar elementos relacionados e separar blocos com funções diferentes.'),('Editorial','Alternar abertura expressiva e páginas de referência. Evitar repetir a mesma grade de cards em todo o material.')])
page('IMAGEM','Pessoas reais.\nContexto respeitado.','Fotografia deve mostrar a vida compartilhada no condomínio e a atenção às decisões cotidianas.', [('Moradores','Participação natural, diversidade de idades e papéis. Evitar poses de executivos ou cenas de confronto.'),('Edifícios','Arquitetura residencial, manutenção e espaços comuns. Não associar uma imagem real a um achado fictício.'),('Documentos','Anonimizar dados e preservar a legibilidade do trecho que interessa.'),('Ilustração','Facetas e relações entre informações. Personagens só em campanha específica, sem armas, infantilização ou estereótipos.')])
page('DADOS','Todo número precisa\nde uma pergunta e uma fonte.','A visualização explica uma comparação. Não serve apenas como textura tecnológica.', [('Unidade e período','Identificar valores e datas junto do gráfico. Eixo de barras inicia em zero.'),('Linha e faixa','Distinguir observação e referência com rótulos, marcas e estilos além da cor.'),('Ausência','Usar traço e explicação. Nunca converter valor ausente em zero.'),('Conclusão','Uma diferença numérica não identifica causa. Mostrar a lacuna que limita a interpretação.')],kind='chart')
page('BENCHMARK','20% acima de qual base?','Demonstração fictícia: junho custa R$ 1.800 por elevador/mês. O limite superior ilustrativo é R$ 1.500.', [('Cálculo','(1.800 / 1.500 - 1) × 100 = 20%. Comparação contra o limite superior, não contra a média.'),('Escopo','Manutenção preventiva, sem peças ou modernização. Jan–jun de 2026. Amostra sintética de 12 observações.'),('Limitação','Aditivo de escopo ausente. Os números não demonstram sobrepreço, economia recuperável ou irregularidade.'),('Próximo passo','Solicitar o aditivo e confirmar peças, plantões e escopo antes de comparar.')],kind='chart')
page('CONFIANÇA','Explicar a qualidade\nda evidência.','Um percentual como “78%” sugere precisão que a metodologia pode não sustentar. V2 usa uma descrição acompanhada de motivo.', [('Limitada','Há lacunas relevantes ou comparabilidade insuficiente. Mostrar exatamente qual é a lacuna.'),('Contextualizada','Fontes e escopo permitem uma comparação útil, ainda sujeita às limitações indicadas.'),('Revisada','Uma pessoa responsável revisou a afirmação e registrou data, escopo e justificativa.'),('Dimensões separadas','Completude documental, comparabilidade e revisão não são a mesma coisa. Não gerar uma nota geral sem método validado.')])
page('PRODUTO','Um achado completo\ncabe numa leitura.','A interface organiza o contexto antes de pedir uma decisão.', [('1 / Contexto','Condomínio, período e indicação clara quando os dados são de demonstração.'),('2 / Achado','Uma afirmação proporcional ao que a evidência sustenta.'),('3 / Base','Gráfico, fonte, método, documentos faltantes e motivo do nível de confiança.'),('4 / Ação','Próxima pergunta ou documento necessário. O microsite V2 inclui uma demonstração navegável dessa estrutura.')])
page('ESTADOS','O que aconteceu\ne o que fazer agora.','Estado comercial, estado de processamento e qualidade da evidência são eixos diferentes.', [('Processamento','Recebido, em análise, concluído ou falhou. Prazo estimado só quando conhecido.'),('Documento faltante','Nome do documento, impacto da ausência e como adicioná-lo.'),('Dado indisponível','Motivo e possibilidade de obter o dado. Não desenhar um gráfico vazio com valores fictícios.'),('Módulo adicional','Benefício, escopo, requisitos e ação comercial. Sem achados borrados, urgência fabricada ou selo comprado.')],kind='status')
page('MOBILE','A evidência acompanha\na tela pequena.','A versão móvel preserva a mesma ordem de leitura, com menos elementos simultâneos.', [('Uma coluna','Contexto, achado, gráfico, fonte e próximo passo.'),('Gráfico legível','Rótulos resumidos, valores acessíveis em tabela e espaço para toque.'),('Ações','Controles de pelo menos 44 px, foco visível e nome claro.'),('Sem cortes','O conteúdo deve refluir. Tabelas extensas podem ter região própria de rolagem, identificada e acessível.')])
page('MOBILIZAÇÃO','Convidar para\nmelhorar a informação.','Uma comunidade útil começa com uma pergunta compartilhada e um objetivo compreensível.', [('Convite','“Estamos reunindo os documentos para entender melhor as despesas. Você pode colaborar.”'),('Antes de compartilhar','Mostrar quem acessará o quê. O preview público nunca inclui moradores, unidades, valores privados ou acusações.'),('Colaboração','Solicitar o documento necessário, explicar sua finalidade e registrar sua origem.'),('Coordenação','Organizar perguntas para a próxima conversa ou assembleia, respeitando permissões e responsabilidades.')])
page('SELO DE GOVERNANÇA','Uma arquitetura\nque ainda exige método.','Os níveis 0–3 são conceitos de interface. Não são certificações emitidas.', [('Nível 0','Base em formação. Estado inicial, nunca certificado.'),('Níveis 1–3','Documentado, Verificável e Referência são nomes provisórios. Critérios e limiares ainda precisam de validação.'),('Em todos os protótipos','Mostrar “CONCEITO / NÃO CERTIFICA”. Usar o mesmo azul e distinguir nível por número e texto.'),('Independência','Pacote comercial, acesso a módulos e nível de governança permanecem sistemas separados.')],kind='seals')
page('VALIDAÇÃO DO SELO','Um selo só vale\ncom escopo verificável.','A publicação futura precisa permitir entender e contestar o que foi avaliado.', [('Campos obrigatórios','Identificador, condomínio, escopo, data da avaliação, validade, versão do método e responsável.'),('Ciclo de vida','Proposto, em revisão, emitido, vencido, suspenso ou revogado.'),('Consulta pública','Exibir apenas informações autorizadas. O detalhe documental continua sujeito a controle de acesso.'),('Antes de lançar','Definir evidências, pesos, critérios de revisão, correção e contestação. Até lá, manter os visuais como conceitos.')])
page('MOVIMENTO','Uma mudança\nque ajuda a perceber.','Motion orienta atenção e confirma uma transição de estado.', [('Interação','120–180 ms para feedback. Não atrasar a ação.'),('Revelação','280–480 ms, easing cubic-bezier(.2,.8,.2,1). Evitar deslocamentos longos.'),('Scan','Uma execução iniciada pelo usuário, até 1.200 ms. Não simular processamento de dados.'),('Redução de movimento','Trocar animação por estado estático equivalente. Não esconder conteúdo antes do JavaScript ou depender de animação para entender.')])
page('SOCIAL','Uma pergunta útil\npor peça.','O sistema social aproxima a marca das decisões do cotidiano.', [('Instagram','1080 × 1080 para uma ideia. Carrossel 1080 × 1350 para desenvolver uma pergunta em etapas.'),('Story','1080 × 1920. Preservar áreas superiores e inferiores para controles da plataforma.'),('LinkedIn','1200 × 627. Evidência e contexto com linguagem clara, sem transformar uma hipótese em manchete.'),('Regra editorial','Títulos legíveis no celular. Um próximo passo. Dados de exemplo marcados como fictícios.')],kind='applications')
page('CARROSSEL','Uma narrativa\nque termina em ação.','Cinco telas ajudam o morador a comparar um contrato com responsabilidade.', [('01 / A pergunta','Este contrato está caro?'),('02 / O escopo','O que o serviço inclui e exclui?'),('03 / A comparação','Qual unidade, período e região estão sendo comparados?'),('04 e 05 / A ação','O que ainda falta? Solicite o documento e formule a pergunta com contexto.')],kind='applications')
page('DOCUMENTOS','Uma leitura estável\npara registrar decisões.','O relatório HTML é a experiência principal. O PDF registra uma versão datada.', [('Capa A4','Nome do relatório, período, escopo, versão e identificação do destinatário quando apropriado.'),('Corpo','Resumo, achado, fontes, limitações, recomendações e histórico de mudanças.'),('Impressão','A versão deste livro para impressão usa papel claro e formato A4 horizontal. É RGB, adequada a impressão de escritório.'),('Gráfica profissional','Conversão CMYK, perfil ICC, sangria e prova de cor dependem do fornecedor. O PDF não é apresentado como PDF/X certificado.')],kind='report')
page('E-MAIL E NEWSLETTER','O assunto informa.\nO conteúdo orienta.','O e-mail deve permitir entender a atualização sem expor o conteúdo privado da análise.', [('Assunto','“Seu Raio-X recebeu novos documentos”. Evitar alerta acusatório ou informação sensível.'),('Corpo','Explicar o que mudou, o que pode ser visto e qual é o próximo passo.'),('Assinatura','Nome, função, Condo Ninja e canal institucional. Sem slogan concorrente.'),('Compatibilidade','Usar HTML simples com fallback de fonte. Para wordmark em imagem, fornecer texto alternativo. Não depender de fontes web no cliente de e-mail.')])
page('APRESENTAÇÕES','Uma ideia central\npor lâmina.','O template 16:9 recebido permanece disponível e editável. A V2 acrescenta o livro como fonte editorial e exemplos de evidência com contexto.', [('Abertura','Nome da análise, público, período e uma ideia principal.'),('Achado','Dado, referência, limitação e próximo passo em ordem.'),('Discussão','Perguntas a confirmar, documentos necessários e responsáveis quando definidos.'),('Encerramento','Decisão pendente ou ação combinada. Nunca usar o selo como prova comercial de qualidade.')])
page('MICROSITE','A marca demonstrada\nem funcionamento.','O microsite V2 apresenta o conceito e permite explorar decisões de identidade e produto.', [('Identidade','Comparação de fundos do logo, amostras de cor com cópia e hierarquia tipográfica.'),('Evidência','Gráfico com eixos, faixa comparável, tabela acessível, fontes e lacunas em dados explicitamente fictícios.'),('Acessibilidade','HTML semântico, navegação por teclado, foco, menu móvel, redução de movimento e refluxo.'),('Entrega','Arquivos modulares e standalone. A versão standalone incorpora também os arquivos associados aos downloads.')])
page('TOKENS','Um nome semântico\npara cada função.','A cor primitiva descreve o tom. O token semântico descreve o papel no componente.', [('Primitivos','Ink, Signal e Paper preservam a paleta estabelecida.'),('Temas','background, surface, text, muted, action, onAction, focus e estados possuem valores próprios.'),('Componentes','Área de toque, espessura de foco, entrelinha e largura de leitura formalizam regras de uso.'),('Consistência','JSON é a fonte. CSS e arquivos de integração são gerados a partir dele. Não se declara compatibilidade DTCG sem formato tipado e validação.')])
page('IMPLEMENTAÇÃO','Integração gradual\nno produto existente.','O pacote V2 é independente e não altera a aplicação Next.js nem a publicação atual.', [('Primeiro','Importar fontes e variables.css em um ambiente de revisão. Conferir caminhos e licenças.'),('Depois','Substituir cores diretas por tokens semânticos nos componentes. Aplicar data-theme.'),('Compatibilidade','A configuração Tailwind v3 usa ESM. A V2 também inclui mapeamento @theme para v4, sem exigir migração.'),('Revisão','Verificar foco, contraste, estados de erro e ausência de dados em fluxos reais antes de adotar.')])
page('GOVERNANÇA EDITORIAL','Uma conclusão\nprecisa ter responsável.','Regras propostas para operar a marca com rastreabilidade.', [('Autor','Registra fonte, período, método e limitação.'),('Revisor','Avalia a afirmação, a comparabilidade e explicações alternativas.'),('Publicação','Identifica versão, data e estado da revisão. Evita dados pessoais desnecessários.'),('Correção','Preserva histórico, informa o que mudou e reavalia conclusões afetadas. Atribuições precisam ser formalizadas pela equipe.')])
page('CHECKLIST','Antes de usar.','Verificar a aplicação completa, além dos arquivos isolados.', [('Marca','Condo Ninja, Goldman Regular 400, proporções e olhos preservados.'),('Informação','Fonte, período, unidade, limites e dados fictícios identificados.'),('Experiência','Foco visível, teclado, contraste, tamanho de toque, mobile e movimento reduzido.'),('Entrega','Assets existentes, links válidos, licenças incluídas, índice e checksums atualizados.')])
page('ARQUIVOS','Uma entrega\nque se pode rastrear.','O índice relaciona caminho, tamanho, hash e origem de cada arquivo.', [('Preservado','Logos, fontes e materiais V1 mantidos recebem identificação de origem no inventário.'),('Evoluído','Brand Book, microsite, tokens, dados, selos, templates e especificações recebem nova revisão.'),('Editável','Fontes JSON, Python, SVG, HTML, CSS e JavaScript acompanham o pacote.'),('Como começar','Abrir START-HERE.html. Consultar 00_Review/REVIEW-V1.md para entender as decisões.')])
page('DECISÕES ABERTAS','Evoluir quando\na evidência permitir.','A V2 especifica o sistema sem inventar uma metodologia operacional que ainda não existe.', [('Símbolo','Aprovar a equivalência do vetor recebido frente ao raster antes de nomeá-lo master definitivo.'),('Governança','Validar critérios, pesos, validade e processo de contestação do selo.'),('Benchmark','Definir amostra, recorte, atualização, comparabilidade e regras por categoria.'),('Produto','Confirmar módulos disponíveis, revisão humana, preços e condições. Protótipos não provam capacidade implementada.')])
page('FECHAMENTO','A informação só ajuda\nquando se pode entendê-la.','Condo Ninja\nClareza para quem paga condomínio.\nSistema de marca 2.0',kind='closing')
dump('01_Brand_Book/source/book-content.json',pages)
print('Wrote',len(pages),'editorial pages, tokens, contrast audit and synthetic dataset.')
